    "replicates": 10000,
    "seed": "BOOTSTRAP_SEED = 20261130",
    "d1_resampling": "within domains, in the order books, c4, fineweb, wikitext (only the domains of the metric); r.choices(windows, k=n_domain); statistic = mean of the domain means; both models use the same drawn windows",
    "d2_resampling": "unstratified, r.choices(items, k=800)",
    "percentile": "interpretation B11 (linear interpolation at (B - 1) * p / 100)",
    "seed_average": "average the 3 seeds' values per unit, then bootstrap; per-seed bootstraps reported; seed min, max and sample SD of the point estimates reported",
    "sigma_N": "sample SD (denominator B - 1) of the 10,000 bootstrap values of N's level statistic on the DEV set: D1 metrics: mean of domain means of NLL_N(w); D2: Acc_D2(N)"
  },
  "gate_d": {
    "G-D1": {
      "control": "Z0",
      "rule": "per seed: reloaded state_sha256 == N's; per-unit differences to N: candidate scores <= 1e-4, D1 window NLL <= 1e-5, D2 letter scores <= 1e-4; predictions identical except near-ties (top-2 gap <= 1e-4 in either evaluation, Pilot G0.8)"
    },
    "G-D2": {
      "rule": "sigma_N(D1-all), sigma_N(D1-diff), sigma_N(D1-same), sigma_N(D2) finite and > 0"
    },
    "G-D3": {
      "control": "P+",
      "D1-diff": {
        "seed_average_min": 1.0,
        "ci95_lower_gt": 0.0,
        "per_seed_min": 0.5
      },
      "D2": {
        "seed_average_min": 0.05,
        "ci95_lower_gt": 0.0,
        "per_seed_gt": 0.0
      }
    },
    "G-D4": {
      "rule": "P+ seed 101: evaluation at the end of training and after save / reload (state_sha256 equal); tolerances as G-D1"
    },
    "G-D5": {
      "rule": "report only: P+ (D1-diff, D2) per seed; after the DEV curves, Spearman correlation of D1-diff and D2 over all trained-model DEV evaluations"
    },
    "pass": "G-D1 and G-D2 and G-D3 and G-D4; otherwise ST14"
  },
  "margin": {
    "formula": "m(M) = 2 * sigma_N(M), M in D1-all, D1-diff, D1-same, D2",
    "multiplier": 2,
    "input_record": "metrix/e1-v1/results/gate_d_record.json (noise)",
    "output_record": "metrix/e1-v1/results/margin_record.json (MARGIN_RECORD)",
    "timing": "after Gate D passes; committed and pushed before any training of section 10 step 6 (ST15)"
  },
  "comparison": {
    "primary": "TEST, t = 0.80, D1-diff, Delta(L-F) and Delta(A-F); Bonferroni over the 2: 97.5% CI",
    "secondary": "all other points, metrics, DEV comparisons and per-method damages: 95% CI, words marked secondary",
    "words": "superior: hi < 0 and all 3 seed estimates < 0; non-inferior: not superior, hi < m and all 3 seed estimates < m; inferior: lo > m and all 3 seed estimates > m; inconclusive otherwise"
  }
}
