protocol "METRIX-E1-PILOT"

version "v1.1"

status "PROTOCOL_FROZEN"

frozen "Owner 批准，2026-11-22 05:27 UTC"

base {"repository": "leotree2020/OpenMythos", "branch": "mythos-idea-thermo-v1", "commit": "61d3c76705b28cc2ee334abc5bf1baaac4fc30dc", "authoring_branch": "metrix-e1-pilot-protocol-v1"}

fact_ids {"learned": "E1P-L-*: 120 facts, each with exactly one TRAIN statement", "unread": "E1P-U-*: 40 facts, no training text in any arm", "assignment": "within a cell, generated facts 01-15 are learned and 16-20 (written as U 01-05) are unread; no fact changes class"}

